"use client";

/**
 * Clarification Dialog Component (Epic #597 / Issue #625).
 *
 * Interactive Q&A interface that lets users answer clarifying questions
 * generated by the requirements enhancement pipeline.
 */
import { useEffect, useRef, useState } from "react";
import { toast } from "sonner";
import { resolveErrorMessage, useAppMutation } from "@/lib/use-app-mutation";
import { ApiError } from "@/lib/api-client";
import {
  analysisApi,
  type ClarificationStatePayload,
  type ClarifyingQuestion,
  type ClarifyingQuestionCitation,
  type ClarifyImportResult,
  type SetAsideClarifyingQuestion,
} from "@/lib/analysis-api";
import { triggerDownload } from "@/lib/plugins-api";
import { formatSourceLabel } from "@/lib/format-source-label";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

/**
 * Issue #1104 (finding C) — every answered round's answered questions, as
 * {@link AnsweredRounds} shows them. Answers come from the question's own
 * `answer` field, falling back to the round's `answers[]` for rounds persisted
 * before the server stamped them.
 */
function answeredRounds(state: ClarificationStatePayload) {
  return state.rounds
    .map((round) => {
      // Rounds persisted by older builds may carry neither array.
      const byId = new Map((round.answers ?? []).map((a) => [a.questionId, a.answer]));
      const answered = (round.questions ?? [])
        .map((q) => ({ ...q, submitted: q.answer ?? byId.get(q.id) }))
        .filter((q) => (q.submitted ?? "").trim().length > 0);
      return { round: round.round, answered };
    })
    .filter((r) => r.answered.length > 0);
}

/**
 * #2032 — the ids of the questions {@link ClarificationDialogPanel} renders
 * with a `#clarify-question-<id>` anchor: the current round's questions while
 * clarification is open, and every answered question once it is complete.
 * An earlier round's question is not on the page while a later round is open.
 */
export function renderedClarifyingQuestionIds(state: ClarificationStatePayload): Set<string> {
  const questions = state.completed
    ? answeredRounds(state).flatMap((r) => r.answered)
    : (state.rounds[state.rounds.length - 1]?.questions ?? []);
  return new Set(questions.map((q) => q.id));
}

/** Issue #1104 (finding C) — read-only Q&A transcript of every answered round. */
export function AnsweredRounds({
  state,
}: {
  state: ClarificationStatePayload;
}): React.ReactElement | null {
  const rounds = answeredRounds(state);

  if (rounds.length === 0) return null;

  return (
    <div className="space-y-3" data-testid="answered-rounds">
      {rounds.map((r) => (
        <div key={r.round} className="space-y-2">
          <p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
            Round {r.round} — {r.answered.length} answered
          </p>
          {r.answered.map((q) => (
            <div
              key={q.id}
              id={`clarify-question-${q.id}`}
              className="scroll-mt-4 rounded border border-border p-3"
            >
              <p className="text-sm font-medium text-foreground">{q.question}</p>
              <p className="mt-1 text-sm text-muted-foreground">{q.submitted}</p>
            </div>
          ))}
        </div>
      ))}
    </div>
  );
}

/**
 * Issue #1081 — say when METIS could not read the model's update for some
 * requirements after the user's answers. The answers still count (they are
 * recorded without a model); what is missing is the rewritten description.
 * Before #1081 this failure left no trace at all.
 */
export function UnreadResolutionsNote({
  state,
}: {
  state: ClarificationStatePayload;
}): React.ReactElement | null {
  const ids = new Set(state.rounds.flatMap((r) => r.unreadResolutions ?? []));
  if (ids.size === 0) return null;
  const count = ids.size;
  return (
    <p
      role="status"
      className="text-xs text-warning"
      data-testid="clarification-unread-resolutions"
    >
      METIS could not read the model’s update for {count} requirement{count === 1 ? "" : "s"} after
      your answers, so {count === 1 ? "its description was" : "their descriptions were"} not
      rewritten from them. Your answers are saved and still count.
    </p>
  );
}

/** #2235 — what kind of uncertainty a question settles, in the analyst's words. */
const UNCERTAINTY_LABEL: Record<NonNullable<ClarifyingQuestion["uncertainty"]>, string> = {
  "missing-knowledge":
    "Missing project knowledge: METIS searched your documents and code before asking",
  ambiguity: "The document can be read more than one way",
  silence: "The document does not say",
  unanswerable: "No one can answer this yet",
};

/** #2235 — the paragraph of the source document a question is about. */
export function QuestionCitation({
  citation,
}: {
  citation: ClarifyingQuestionCitation;
}): React.ReactElement {
  const where = [citation.filename, ...citation.headingPath].filter(Boolean).join(" › ");
  return (
    <figure
      className="mb-2 rounded border-l-2 border-border bg-muted px-2 py-1"
      data-testid="question-citation"
    >
      {where && <figcaption className="text-xs text-muted-foreground">{where}</figcaption>}
      <blockquote className="whitespace-pre-line text-xs text-foreground">
        {citation.quote}
      </blockquote>
    </figure>
  );
}

/**
 * #2235 — the plausible readings a question offers. Picking one puts it in the
 * answer box, where it can still be edited; nothing is submitted until Submit.
 */
export function QuestionOptions({
  question,
  onPick,
}: {
  question: ClarifyingQuestion;
  onPick: (option: string) => void;
}): React.ReactElement | null {
  const options = question.options ?? [];
  if (options.length === 0) return null;
  return (
    <div
      role="group"
      aria-label="Possible answers"
      className="mb-2 flex flex-wrap gap-2"
      data-testid="question-options"
    >
      {options.map((option) => (
        <Button
          key={option}
          type="button"
          variant="outline"
          size="sm"
          aria-describedby={`clarify-label-${question.id}`}
          onClick={() => onPick(option)}
        >
          {option}
        </Button>
      ))}
    </div>
  );
}

const SET_ASIDE_HEADING: Record<SetAsideClarifyingQuestion["reason"], string> = {
  unanswerable: "Open items: no one can answer these yet, so they are recorded and not asked",
  "same-outcome": "Not asked: every reading of these builds the same thing",
};

/**
 * #2235 — the questions METIS did not ask, and why. Listed so that nothing
 * raised about the document disappears without a trace.
 */
export function SetAsideQuestions({
  state,
}: {
  state: ClarificationStatePayload;
}): React.ReactElement | null {
  const setAside = state.setAside ?? [];
  if (setAside.length === 0) return null;
  const groups = (["unanswerable", "same-outcome"] as const)
    .map((reason) => ({ reason, items: setAside.filter((q) => q.reason === reason) }))
    .filter((g) => g.items.length > 0);
  return (
    <details className="text-sm" data-testid="clarification-set-aside">
      <summary className="cursor-pointer text-xs text-muted-foreground">
        {setAside.length} question{setAside.length === 1 ? "" : "s"} not asked
      </summary>
      <div className="mt-2 space-y-3">
        {groups.map((g) => (
          <div key={g.reason} className="space-y-2" data-testid={`set-aside-${g.reason}`}>
            <p className="text-xs font-medium text-muted-foreground">
              {SET_ASIDE_HEADING[g.reason]}
            </p>
            {g.items.map((q) => (
              <div
                key={`${q.requirementId}:${q.ambiguityField}:${q.round}`}
                className="rounded border border-border p-2"
              >
                <p className="text-sm text-foreground">{q.question}</p>
                {q.context && <p className="text-xs text-muted-foreground">{q.context}</p>}
                {q.citation && <QuestionCitation citation={q.citation} />}
              </div>
            ))}
          </div>
        ))}
      </div>
    </details>
  );
}

/**
 * #2236 — the questions METIS did not ask because the project had already
 * answered them, with the answer that was reused. Listed so the analyst sees
 * what was carried over and can tell a settled question from a skipped one.
 */
export function ReusedAnswers({
  state,
}: {
  state: ClarificationStatePayload;
}): React.ReactElement | null {
  const reused = state.reused ?? [];
  if (reused.length === 0) return null;
  return (
    <details className="text-sm" data-testid="clarification-reused">
      <summary className="cursor-pointer text-xs text-muted-foreground">
        {reused.length} question{reused.length === 1 ? "" : "s"} already answered in this project,
        not asked again
      </summary>
      <div className="mt-2 space-y-2">
        {reused.map((r) => (
          <div
            key={`${r.recordId}:${r.requirementId}:${r.round}`}
            className="rounded border border-border p-2"
          >
            <p className="text-sm text-foreground">{r.question}</p>
            <p className="text-sm text-foreground">
              <span className="font-medium">Answer: </span>
              {r.answer}
            </p>
            <p className="text-xs text-muted-foreground">
              Answered {new Date(r.answeredAt).toLocaleDateString()}
              {r.fromAnalysisId ? " in an earlier analysis" : ""}
            </p>
            {r.citation && <QuestionCitation citation={r.citation} />}
          </div>
        ))}
      </div>
    </details>
  );
}

/**
 * #2235 — a round asks at most a fixed number of questions, the highest-impact
 * first. Say how many more are waiting, or, on the last round, that they will
 * not be asked.
 */
export function NotAskedNote({
  state,
}: {
  state: ClarificationStatePayload;
}): React.ReactElement | null {
  const last = state.rounds[state.rounds.length - 1];
  const count = last?.notAsked ?? 0;
  if (count === 0) return null;
  const more = `${count} more question${count === 1 ? "" : "s"}`;
  const lastRound = (last?.round ?? 0) >= state.maxRounds;
  return (
    <p
      role="status"
      className="text-xs text-muted-foreground"
      data-testid="clarification-not-asked"
    >
      {lastRound
        ? `${more} did not fit in the last round and ${count === 1 ? "was" : "were"} not asked.`
        : `${more} of lower impact ${count === 1 ? "is" : "are"} waiting for the next round.`}
    </p>
  );
}

/**
 * #2085 — the dialog's current round has not been generated yet: a submit
 * left something open, and the start that generates the next round is in
 * flight, failed, or cannot be sent by this viewer.
 */
export interface NextRoundStatus {
  /** The start that generates the round is in flight. */
  preparing: boolean;
  /** It round-tripped and failed. */
  failed: boolean;
  /** #1081 — it failed because the model's questions could not be read. */
  unreadable: boolean;
  /** This viewer may send the start (holds `analysis.run`, has a requirement list). */
  canStart: boolean;
  onRetry: () => void;
}

interface ClarificationDialogProps {
  projectId: string;
  analysisId: string;
  state: ClarificationStatePayload;
  /** #2085 — set while the current round is due and not yet generated. */
  nextRound?: NextRoundStatus;
  /**
   * `state` is the dialog as the submit or import left it. Absent when the
   * server sent none, and (#2101) when the round was no longer open: the
   * caller then reads the dialog again.
   */
  onComplete: (state?: ClarificationStatePayload) => void;
}

/**
 * #2085 — shown in place of the questions and Submit while the next round is
 * due. The round on screen is already answered: the server refuses (409) a
 * second submit to it, and before that refusal one was a lost update.
 */
function NextRoundNotice({
  round,
  status,
}: {
  round: number;
  status: NextRoundStatus;
}): React.ReactElement {
  if (status.failed && !status.preparing) {
    return (
      <p role="alert" data-testid="clarify-round-error" className="text-sm text-destructive">
        {status.unreadable
          ? `METIS could not read the clarifying questions in the model’s answer, so round ${round} was not started. This does not mean there is nothing to clarify.`
          : `Could not prepare round ${round} of the clarifying questions.`}{" "}
        <button type="button" onClick={status.onRetry} className="underline hover:text-destructive">
          Try again
        </button>
      </p>
    );
  }
  return (
    <p
      role="status"
      data-testid="clarify-round-preparing"
      className="text-sm text-muted-foreground"
    >
      {status.preparing || status.canStart
        ? `Preparing round ${round} of the clarifying questions from your answers…`
        : `Round ${round} of the clarifying questions has not been prepared yet.`}
    </p>
  );
}

/** #2085 / #2101 — the server refused answers because their round is no longer open. */
function roundNotOpen(error: unknown): boolean {
  return error instanceof ApiError && error.code === "CLARIFY_ROUND_NOT_OPEN";
}

/** #2142 — what a submit and an import both say when their round had closed. */
const ROUND_CLOSED_MESSAGE = "This round was already answered. Showing the current questions.";

export function ClarificationDialogPanel({
  projectId,
  analysisId,
  state,
  nextRound,
  onComplete,
}: ClarificationDialogProps): React.ReactElement {
  const currentRound = state.rounds[state.rounds.length - 1];
  const questions = currentRound?.questions ?? [];

  // Self-resolution: a grounded/partial question OFFERS the server's suggested
  // answer beside its box; it is never filled in. #2122 — pre-filled boxes read
  // "9 of 28 answered" before the BA typed anything, and Submit sent every one:
  // a wrong suggestion submitted by accident settled a governing finding. A box
  // holds only what the user typed, accepted or submitted before.
  const seedAnswers = (): Record<string, string> => {
    const seed: Record<string, string> = {};
    const submitted = new Map((currentRound?.answers ?? []).map((a) => [a.questionId, a.answer]));
    for (const q of questions) {
      // Issue #1104 (finding C) — an answer the user already submitted is kept;
      // re-opening a round must never blank their work.
      const prior = q.answer ?? submitted.get(q.id);
      if (prior) seed[q.id] = prior;
    }
    return seed;
  };
  const [answers, setAnswers] = useState<Record<string, string>>(seedAnswers);

  // Issue #1117 (finding D) — re-seed when the PERSISTED ANSWERS change, not
  // only when the question set does.
  //
  // The reported symptom was a transient "0 of 14 answered" with blank inputs
  // straight after Submit, while the server already held all 14. The cause was a
  // two-part race: `onSuccess` cleared local state synchronously, and this
  // effect keyed on question ids alone — so if the refetch came back with the
  // same round (which is the normal case), nothing re-seeded and the form stayed
  // empty until a full reload. Right after #1104/#1116 fixed real answer loss on
  // this exact screen, that reads as the bug coming back.
  const questionKey = questions
    .map((q) => `${q.id}=${(q.answer ?? "").length}`)
    .concat((currentRound?.answers ?? []).map((a) => `${a.questionId}=${a.answer.length}`))
    .join("|");
  useEffect(() => {
    setAnswers(seedAnswers());
  }, [questionKey]);

  // Epic #201 (#213) — when resuming a persisted dialog, surface which
  // ambiguities are already addressed vs. still remaining in this round.
  //
  // Issue #1117 (finding A) — "remaining" is now measured against everything
  // ADDRESSED (answered by the user OR closed by the resolution model), not
  // against the model's tally alone. The reported run answered 14 questions and
  // read "1 resolved / 13 remaining", which told the user their work had not
  // taken when in fact all 14 answers had persisted.
  const answeredCount = Object.values(answers).filter((a) => a.trim().length > 0).length;
  //
  // #2128 — counted across the session, and a governing answer counts too:
  // round 2 opened at "0 addressed" after round 1's only answer, a governing
  // one, was accepted. Keyed by question id, so the same rule asked again in a
  // later round is still remaining until that question is answered.
  const addressedFields = new Set([
    ...state.resolvedAmbiguities,
    ...(state.answeredAmbiguities ?? []),
    ...state.rounds
      .flatMap((r) => r.questions ?? [])
      .filter((q) => q.governing && q.answer?.trim())
      .map((q) => `question:${q.id}`),
  ]);
  const remainingFields = questions
    .map((q) => `${q.requirementId}:${q.ambiguityField}`)
    .filter((key) => !addressedFields.has(key));
  const addressedCount = addressedFields.size;
  /** What the resolution model claimed — reported separately, never as progress. */
  const modelConfirmedCount = state.resolvedAmbiguities.length;

  // #241 — clarification submit: success/error toasts + pending button state.
  //
  // Issue #1104 (finding C) — the submit response is `{ state, … }`, so the old
  // `result.completed` read was ALWAYS undefined: the panel never refetched and
  // kept rendering the pre-submit round ("0 resolved / 12 remaining") as though
  // the answers had gone nowhere. Refresh on every successful submit.
  const submitMutation = useAppMutation({
    mutationFn: () =>
      analysisApi.submitClarifyAnswers(
        projectId,
        analysisId,
        // #2122 — only the boxes the user filled: a blank box is no answer.
        Object.entries(answers)
          .filter(([, answer]) => answer.trim().length > 0)
          .map(([questionId, answer]) => ({ questionId, answer })),
      ),
    successMessage: (result) =>
      result.state?.completed ? "Clarification complete" : "Answers submitted",
    errorMessage: (error) =>
      roundNotOpen(error)
        ? ROUND_CLOSED_MESSAGE
        : resolveErrorMessage(error, "Failed to submit answers"),
    // Issue #1117 (finding D) — do NOT clear the answers here. Blanking local
    // state in the same tick left a window where the panel showed nothing
    // while the server held everything. `onComplete` puts the submit's own
    // state straight into the query cache (#2085), and the re-seed effect
    // above takes it, so a new round arrives with fresh (empty) inputs and a
    // re-rendered current round keeps the user's text on screen throughout.
    onSuccess: (result) => {
      onComplete(result.state);
    },
    // #2101 — the round closed under this tab (answered elsewhere, or a later
    // one was generated): read the dialog again, so the panel moves to the
    // current round in place instead of offering Submit on the closed one.
    onError: (error) => {
      if (roundNotOpen(error)) onComplete();
    },
  });

  // Business Analyst CSV round-trip: export the current round's questions,
  // answer offline, re-import. Import applies answers via the existing submit
  // path server-side; #2101 — and answers with the state it wrote, which
  // `onComplete` takes at once (it reads the dialog again when there is none).
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [importSummary, setImportSummary] = useState<ClarifyImportResult | null>(null);

  const exportMutation = useAppMutation({
    mutationFn: () => analysisApi.exportClarifyCsv(projectId, analysisId),
    successMessage: "Questions exported",
    errorMessage: "Failed to export questions",
    onSuccess: ({ blob, filename }) => {
      triggerDownload(blob, filename);
    },
  });

  const importMutation = useAppMutation({
    mutationFn: (file: File) => analysisApi.importClarifyAnswers(projectId, analysisId, file),
    successMessage: (result) =>
      `Imported ${result.applied} answer(s)` +
      (result.unmatched.length > 0 ? ` — ${result.unmatched.length} unmatched` : ""),
    errorMessage: false, // surface the raw thrown message verbatim (below).
    onSuccess: (result) => {
      setImportSummary(result);
      onComplete(result.state);
    },
    onError: (error) => {
      // #2101 — as a submit: the round closed, so move to the current one.
      // #2142 — and say so in the submit's words, not the server's raw text.
      if (roundNotOpen(error)) {
        toast.error(ROUND_CLOSED_MESSAGE);
        onComplete();
        return;
      }
      toast.error(error instanceof Error ? error.message : "Failed to import answers");
    },
  });

  const onFilePicked = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    // Reset so picking the same file twice still fires onChange.
    e.target.value = "";
    if (file) {
      importMutation.mutate(file);
    }
  };

  const csvActions = (
    <div className="flex items-center gap-2">
      <Button
        variant="outline"
        size="sm"
        onClick={() => exportMutation.mutate()}
        disabled={exportMutation.isPending}
      >
        {exportMutation.isPending ? "Exporting…" : "Export questions"}
      </Button>
      <Button
        variant="outline"
        size="sm"
        onClick={() => fileInputRef.current?.click()}
        disabled={importMutation.isPending}
      >
        {importMutation.isPending ? "Importing…" : "Import answers"}
      </Button>
      <input
        ref={fileInputRef}
        type="file"
        accept=".csv"
        className="hidden"
        data-testid="clarify-import-input"
        onChange={onFilePicked}
      />
    </div>
  );

  if (state.completed) {
    return (
      <Card className="space-y-3 p-4" data-testid="clarification-complete">
        <div className="flex items-center gap-2">
          <span className="text-success">✓</span>
          <h3 className="font-semibold">Clarification Complete</h3>
        </div>
        {/* Issue #1117 (finding A) — lead with what the USER did. The old line
            reported the resolution model's tally ("1 ambiguities resolved")
            after fourteen substantive answers, which reads as thirteen answers
            having been thrown away. */}
        <p className="text-sm text-muted-foreground">
          {addressedCount} question{addressedCount === 1 ? "" : "s"} addressed across{" "}
          {state.rounds.length} round(s).
          {state.escalatedToSonnet && (
            <span className="ml-1 text-warning">(Escalated to Sonnet for complex resolution)</span>
          )}
        </p>
        {modelConfirmedCount < addressedCount && (
          <p className="text-xs text-muted-foreground" data-testid="clarification-model-confirmed">
            METIS confirmed {modelConfirmedCount} of these as fully resolved. The rest are recorded
            from your answers and carried into the analysis either way — no answer was discarded.
          </p>
        )}
        <UnreadResolutionsNote state={state} />
        <NotAskedNote state={state} />
        {/* Issue #1104 (finding C) — the answers the user wrote are part of the
            analysis record, so show them. A bare "complete" summary is how a
            dozen hand-written answers became unreachable through the UI. */}
        <AnsweredRounds state={state} />
        <ReusedAnswers state={state} />
        <SetAsideQuestions state={state} />
      </Card>
    );
  }

  const roundBadge = (
    <span className="rounded border border-border bg-muted px-2 py-0.5 text-xs text-muted-foreground">
      Round {state.currentRound} / {state.maxRounds}
    </span>
  );

  // #2085 — no questions, no Submit and no CSV round-trip while the next round
  // is due: every one of them would act on the round already answered.
  if (nextRound) {
    return (
      <Card className="space-y-4 p-4" data-testid="clarification-next-round">
        <div className="flex items-center justify-between gap-3">
          <h3 className="text-lg font-semibold">Clarifying Questions</h3>
          {roundBadge}
        </div>
        <NextRoundNotice round={state.currentRound} status={nextRound} />
        <UnreadResolutionsNote state={state} />
      </Card>
    );
  }

  return (
    <Card className="space-y-4 p-4">
      <div className="flex items-center justify-between gap-3">
        <h3 className="text-lg font-semibold">Clarifying Questions</h3>
        <div className="flex items-center gap-2">
          {csvActions}
          {roundBadge}
        </div>
      </div>
      <p className="text-sm text-muted-foreground">
        Please answer these questions to resolve requirement ambiguities. You can also export them
        to CSV, answer offline, and re-import the file.
      </p>

      {importSummary && (
        <p className="text-xs text-muted-foreground" data-testid="clarify-import-summary">
          Imported {importSummary.applied} answer(s); {importSummary.skipped} skipped
          {importSummary.unmatched.length > 0 && (
            <> ; unmatched: {importSummary.unmatched.join(", ")}</>
          )}
          .
        </p>
      )}

      {/* Epic #201 (#213) — addressed vs remaining, rehydrated from persisted state. */}
      <div className="flex flex-wrap gap-2 text-xs" data-testid="clarification-progress">
        <span className="rounded bg-success-muted px-2 py-0.5 text-success">
          {addressedFields.size} addressed
        </span>
        <span className="rounded bg-warning-muted px-2 py-0.5 text-warning">
          {remainingFields.length} remaining
        </span>
        {/* Issue #1104 (finding C) — "0 resolved" said nothing about the twelve
            answers already submitted. Count them explicitly. */}
        <span className="rounded bg-muted px-2 py-0.5 text-foreground">
          {answeredCount} of {questions.length} answered
        </span>
      </div>
      <UnreadResolutionsNote state={state} />
      <NotAskedNote state={state} />

      <div className="space-y-4">
        {questions.map((q: ClarifyingQuestion) => {
          const grounded = q.groundingStatus === "grounded";
          const partial = q.groundingStatus === "partial";
          const isSelfResolved = grounded || partial;
          // #573 — one entry per (cited name, stored source), labelled on that
          // source: a legacy upload and a repo row sharing a name are two
          // different documents and must not collapse into one label.
          const sources = [
            ...new Map(
              (q.groundingCitations ?? [])
                .filter((c) => c.source)
                .map((c) => [
                  `${c.documentSource ?? ""}\u0000${c.source}`,
                  formatSourceLabel(c.source, undefined, c.documentSource),
                ]),
            ).values(),
          ];

          return (
            <div
              key={q.id}
              // #1876 — a governing finding's "Answer the clarifying question" link.
              id={`clarify-question-${q.id}`}
              className="scroll-mt-4 rounded border border-border p-3"
              data-testid={isSelfResolved ? "grounded-question" : "open-question"}
            >
              <Label
                htmlFor={`clarify-answer-${q.id}`}
                id={`clarify-label-${q.id}`}
                className="mb-1 block text-sm font-medium"
              >
                {q.question}
              </Label>
              {q.context && <p className="mb-2 text-xs text-muted-foreground">{q.context}</p>}
              {q.uncertainty && (
                <p
                  className="mb-2 text-xs text-muted-foreground"
                  data-testid="question-uncertainty"
                >
                  {UNCERTAINTY_LABEL[q.uncertainty]}
                </p>
              )}
              {q.citation && <QuestionCitation citation={q.citation} />}
              <QuestionOptions
                question={q}
                onPick={(option) => setAnswers((prev) => ({ ...prev, [q.id]: option }))}
              />
              {/* #1081 — open because the check failed, not because a model judged it. */}
              {q.groundingFailed && !isSelfResolved && (
                <p className="mb-2 text-xs text-warning" data-testid="grounding-failed">
                  METIS could not check your project’s documents and code for an answer to this
                  question, so none is suggested.
                </p>
              )}

              {isSelfResolved && (
                <div className="mb-2 space-y-1">
                  <span
                    className={
                      grounded
                        ? "inline-block rounded bg-success-muted px-2 py-0.5 text-xs text-success"
                        : "inline-block rounded bg-warning-muted px-2 py-0.5 text-xs text-warning"
                    }
                    data-testid="grounding-badge"
                  >
                    {grounded
                      ? "Suggested from project knowledge — not answered until you use it"
                      : "Partly suggested from project knowledge — review before you use it"}
                  </span>
                  {sources.length > 0 && (
                    // #427 — render human-readable source labels (basename — repo)
                    // instead of raw `connector:repo:…` ids; keep the full raw ids
                    // in the tooltip for copy/deep-link.
                    <p
                      className="text-xs text-muted-foreground"
                      data-testid="suggested-answer-source"
                      title={sources.map((s) => s.rawId).join(", ")}
                    >
                      Suggested answer (from {sources.map((s) => s.label).join(", ")})
                    </p>
                  )}
                  {q.groundedAnswer && (
                    <div className="flex items-start justify-between gap-2 rounded bg-muted px-2 py-1">
                      <p className="text-xs text-foreground" data-testid="suggested-answer">
                        {q.groundedAnswer}
                      </p>
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        aria-describedby={`clarify-label-${q.id}`}
                        onClick={() =>
                          setAnswers((prev) => ({ ...prev, [q.id]: q.groundedAnswer ?? "" }))
                        }
                      >
                        Use suggested answer
                      </Button>
                    </div>
                  )}
                </div>
              )}

              <Input
                id={`clarify-answer-${q.id}`}
                placeholder={
                  isSelfResolved ? "Your answer, or use the suggestion above…" : "Your answer..."
                }
                value={answers[q.id] ?? ""}
                onChange={(e) => setAnswers((prev) => ({ ...prev, [q.id]: e.target.value }))}
              />
            </div>
          );
        })}
      </div>

      <div className="flex items-center justify-between pt-2">
        {/* Issue #1117 (finding A) — count the user's own answers, not the
            resolution model's confirmations. */}
        <p className="text-xs text-muted-foreground">
          {addressedCount} question{addressedCount === 1 ? "" : "s"} addressed so far
        </p>
        <Button
          onClick={() => submitMutation.mutate()}
          disabled={submitMutation.isPending || answeredCount === 0}
        >
          {submitMutation.isPending ? "Submitting…" : "Submit Answers"}
        </Button>
      </div>

      {submitMutation.isError && (
        <p className="text-sm text-destructive">Failed to submit answers. Please try again.</p>
      )}
      <ReusedAnswers state={state} />
      <SetAsideQuestions state={state} />
    </Card>
  );
}
